from __future__ import annotations

from typing import Any, Callable

ProgressCb = Callable[[dict[str, Any]], None]
CancelCheck = Callable[[], None]

BACKEND_OPUS = "opus-ct2"  # retired; kept so old requests can be rejected by name
BACKEND_EXTERNAL = "external"
BACKEND_LLAMA = "llama"
KNOWN_MT_BACKENDS = (BACKEND_EXTERNAL, BACKEND_LLAMA)
_RETIRED_OPUS_ALIASES = frozenset({"opus", "opus-ct2", "ct2", "marian", "local"})


def pick_mt_model(language: str, explicit: str | None = None) -> str:
    raise ValueError("Opus MT 已停用。请使用 mtBackend=llama 或 mtBackend=external。")


def normalize_mt_backend(value: Any) -> str:
    raw = str(value or "").strip().lower().replace("_", "-")
    if raw in _RETIRED_OPUS_ALIASES:
        raise ValueError(
            "Opus MT（opus-ct2）已停用。请使用推理翻译 mtBackend=llama 或智能翻译 mtBackend=external。"
        )
    if not raw:
        return BACKEND_LLAMA
    aliases = {
        "external": BACKEND_EXTERNAL,
        "llm-external": BACKEND_EXTERNAL,
        "http": BACKEND_EXTERNAL,
        "llama": BACKEND_LLAMA,
        "llama-server": BACKEND_LLAMA,
        "gguf": BACKEND_LLAMA,
        "sakura": BACKEND_LLAMA,
        "llm": BACKEND_LLAMA,
    }
    backend = aliases.get(raw, raw)
    if backend not in KNOWN_MT_BACKENDS:
        raise ValueError(
            f"unsupported mtBackend: {value!r} (expected external|llama)"
        )
    return backend


def translate_cues(
    cues: list[dict[str, Any]],
    *,
    language: str = "en",
    mt_model: str | None = None,
    device: str = "auto",
    mt_backend: str | None = None,
    mt_external: dict[str, Any] | None = None,
    mt_llama: dict[str, Any] | None = None,
    job_id: str | None = None,
    target_language: str = "zh",
    on_progress: ProgressCb | None = None,
    cancel_check: CancelCheck | None = None,
) -> list[dict[str, Any]]:
    backend = normalize_mt_backend(mt_backend)

    if backend == BACKEND_EXTERNAL:
        from .external_http import external_translate_cues

        return external_translate_cues(
            cues,
            mt_external=mt_external,
            language=language,
            target_language=target_language,
            job_id=job_id,
            on_progress=on_progress,
            cancel_check=cancel_check,
        )

    if backend == BACKEND_LLAMA:
        from .llama_http import llama_translate_cues

        return llama_translate_cues(
            cues,
            mt_llama=mt_llama,
            language=language,
            target_language=target_language,
            job_id=job_id,
            on_progress=on_progress,
            cancel_check=cancel_check,
        )

    raise ValueError("Opus MT 已停用。请使用 mtBackend=llama 或 mtBackend=external。")
